const sheetId = 957714022;
const headers = ['ID do lead','Google Place ID','Empresa','Endereço','Site','Telefone','Categorias no Google','Nota no Google','Avaliações no Google','Situação no Google','Encontrado em','Aderência','Complexidade','Facilidade de contato','Prioridade','Motivo da prioridade','Etapa','Próxima verificação','Responsável','Revisado em','Decisor','Canal de contato','Destino do contato','Primeiro contato em','Próximo retorno','Resultado comercial','Não contatar','Motivo da perda','Busca de origem','Cidade','Segmento','ID da empresa','Situação do diagnóstico','Formulário do diagnóstico','Mensagem do convite','Enviar convite','Convite enviado em','Última resposta em','Quem respondeu','Quem falta responder','Sessões recebidas','Respostas válidas','Índice PRUMO','Resultado por área','Lacunas observadas','Briefing interno','Próxima ação','Diagnóstico concluído em','Atualizado em','Erro técnico'];
