const requests = [
  { updateCells: { range: range(0, 50, 0, 1), rows: [{ values: headers.map((header, index) => ({ userEnteredValue: { stringValue: header }, ...(notes[index] ? { note: notes[index] } : {}) })) }], fields: 'userEnteredValue,note' } },
  { repeatCell: { range: range(0, 2, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.25, 0.29, 0.31)) }, fields: 'userEnteredFormat' } },
  { repeatCell: { range: range(2, 11, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.08, 0.25, 0.21)) }, fields: 'userEnteredFormat' } },
  { repeatCell: { range: range(11, 18, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.43, 0.27, 0.06)) }, fields: 'userEnteredFormat' } },
  { repeatCell: { range: range(18, 31, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.12, 0.27, 0.42)) }, fields: 'userEnteredFormat' } },
  { repeatCell: { range: range(31, 50, 0, 1), cell: { userEnteredFormat: headerFormat(color(0.32, 0.17, 0.38)) }, fields: 'userEnteredFormat' } },
