  { updateSheetProperties: { properties: { sheetId, gridProperties: { frozenRowCount: 1, frozenColumnCount: 3 } }, fields: 'gridProperties.frozenRowCount,gridProperties.frozenColumnCount' } },
  { updateDimensionProperties: { range: { sheetId, dimension: 'ROWS', startIndex: 0, endIndex: 1 }, properties: { pixelSize: 48 }, fields: 'pixelSize' } },
  { updateDimensionProperties: { range: { sheetId, dimension: 'ROWS', startIndex: 1, endIndex: 1000 }, properties: { pixelSize: 34 }, fields: 'pixelSize' } },
  { autoResizeDimensions: { dimensions: { sheetId, dimension: 'COLUMNS', startIndex: 0, endIndex: 50 } } },
  { setDataValidation: { range: range(16, 17, 1, 1000), rule: { condition: { type: 'ONE_OF_LIST', values: ['Revisar','Contato aceito','Convite pronto','Diagnóstico em andamento','Diagnóstico para revisar','Concluído','Fora do perfil','Erro na descoberta'].map(userEnteredValue => ({ userEnteredValue })) }, strict: true, showCustomUi: true } } },
  { setDataValidation: { range: range(32, 33, 1, 1000), rule: { condition: { type: 'ONE_OF_LIST', values: ['Não iniciado','Convite pronto','Convite enviado','Aguardando respostas','Revisão necessária','Concluído'].map(userEnteredValue => ({ userEnteredValue })) }, strict: true, showCustomUi: true } } },
  { setBasicFilter: { filter: { range: range(0, 50, 0, 1000) } } },
