  22: 'Informe um link wa.me, número WhatsApp confirmado ou e-mail. Telefone fixo não entra automaticamente aqui.',
  23: 'Data do primeiro contato efetivo.',
  24: 'Data combinada para o próximo retorno.',
  25: 'Resultado atual da abordagem comercial.',
  26: 'Selecione Sim para impedir novas abordagens.',
  27: 'Explique por que o lead foi encerrado ou descartado.',
  32: 'Depois de enviar de verdade, mude de “Convite pronto” para “Convite enviado”.',
  36: 'Data do envio efetivo do convite.'
};
for (const [column, note] of Object.entries(notes)) requests.push({ updateCells: { range: range(Number(column), Number(column) + 1, 0, 1), rows: [{ values: [{ note }] }], fields: 'note' } });
return [{ json: { requests } }];
